import { Component } from '@angular/core';
import { ArtikalService } from '../artikal.service';
import { Artikal } from '../models/artikal';
import { KorisnikService } from '../korisnik.service'; // Uvezi servis za korisnika
import jwt_decode from 'jwt-decode'; // Uvezi jwt-decode za token

@Component({
  selector: 'app-zenskaodeca',
  templateUrl: './zenskaodeca.component.html',
  styleUrls: ['./zenskaodeca.component.css']
})
export class ZenskaodecaComponent {
  artikli: Artikal[] = [];
  filteredArtikli: Artikal[] = [];
  favourites: string[] = []; // Lista omiljenih artikala korisnika
  userId: string = ''; // ID korisnika

  // Filter kriterijumi
  selectedTip: string = ''; // Ovo će biti postavljeno kad se izabere tip
  selectedVelicina: string = '';
  selectedBoja: string = '';
  minCena: number | null = null;
  maxCena: number | null = null;

  constructor(
    private artikalService: ArtikalService,
    private korisnikService: KorisnikService
  ) {}

  ngOnInit(): void {
    const token = localStorage.getItem('token');
    if (token) {
      const decodedToken: any = jwt_decode(token);
      this.userId = decodedToken.id; 
      this.fetchFavourites(); 
      this.fetchArtikli();
    }
    else {
      this.fetchArtikli();
    }
  }

  isLoggedIn(): boolean {
    return this.korisnikService.isLoggedIn();
  }

  // Dohvatanje artikala
  fetchArtikli() {
    this.artikalService.getArtikliByCategory('zenski').subscribe(
      (response) => {
        this.artikli = response.artikli;
        this.filteredArtikli = this.artikli;
      },
      (error) => {
        console.error('Greška pri dohvatanju artikala:', error);
      }
    );
  }

  // Funkcija za postavljanje filtera za tip
  setTipFilter(tip: string) {
    this.selectedTip = tip;
    this.applyFilters();
  }

  // Funkcija za primenu filtera
  applyFilters() {
    this.filteredArtikli = this.artikli.filter(artikal => {
      const matchesTip = this.selectedTip ? artikal.tip === this.selectedTip : true;
      const matchesVelicina = this.selectedVelicina ? artikal.velicina === this.selectedVelicina : true;
      const matchesBoja = this.selectedBoja ? artikal.boja === this.selectedBoja : true;
      const matchesCena = (!this.minCena || artikal.cena >= this.minCena) && (!this.maxCena || artikal.cena <= this.maxCena);

      return matchesTip && matchesVelicina && matchesBoja && matchesCena;
    });
  }

  // Dohvati omiljene artikle korisnika
  fetchFavourites() {
    this.korisnikService.getFavourites(this.userId).subscribe(
      (response) => {
        this.favourites = response.favourites.map((artikal: any) => artikal._id);
      },
      (error) => {
        console.error('Greška pri dohvatanju omiljenih:', error);
      }
    );
  }

  // Funkcija za dodavanje/uklanjanje artikla iz omiljenih
  toggleFavourite(artikalId: string) {
    if (this.favourites.includes(artikalId)) {
      console.log("tu");
      this.korisnikService.removeFromFavourites(this.userId, artikalId).subscribe(() => {
        this.favourites = this.favourites.filter(id => id !== artikalId);
      });
    } else {
      this.korisnikService.addToFavourites(this.userId, artikalId).subscribe(() => {
        this.favourites.push(artikalId);
      });
    }
  }

  // Proveri da li je artikal u omiljenim
  isFavourite(artikalId: string): boolean {
    return this.favourites.includes(artikalId);
  }

  // Funkcija za dohvatanje slike artikla
  getArtikalImage(imagePath: string): string {
    return `http://localhost:4000/${imagePath}`;
  }

  addToCart(artikalId: string) {
    this.korisnikService.addToCart(this.userId, artikalId).subscribe(
      () => {
        console.log('Artikal dodat u korpu');
        this.korisnikService.getCartCount(this.userId).subscribe(); 
      },
      (error) => {
        console.error('Greška pri dodavanju u korpu:', error);
      }
    );
  }

}
<div class="shop-girls-page">

  <div class="shop-layout">
    <!-- Sidebar za tipove artikala -->

    <div class="tipovi-sidebar">
            <ul class="tipovi-list">
        <li><a  (click)="setTipFilter('')">Svi tipovi</a></li>
        <li><a  (click)="setTipFilter('majica')">Majica</a></li>
        <li><a  (click)="setTipFilter('haljina')">Haljina</a></li>
        <li><a  (click)="setTipFilter('farmerice')">Farmerice</a></li>
        <li><a  (click)="setTipFilter('jakna')">Jakna</a></li>
        <li><a  (click)="setTipFilter('duks')">Duks</a></li>
        <li><a  (click)="setTipFilter('suknja')">Suknja</a></li>
        <li><a  (click)="setTipFilter('kaput')">Kaput</a></li>
        <li><a  (click)="setTipFilter('kosulja')">Košulja</a></li>
        <li><a  (click)="setTipFilter('sorts')">Šorts</a></li>
        <li><a  (click)="setTipFilter('trenirka')">Trenerka</a></li>
        <li><a  (click)="setTipFilter('bluza')">Bluza</a></li>
      </ul>
    </div>


    <!-- Glavni sadržaj sa filterima i artiklima -->

    <div class="main-content">
      <div *ngIf="!isLoggedIn()" class="login-prompt">
        <p>Za prijavljivanje ili registraciju <a routerLink="/login">kliknite ovde</a>.</p>
      </div>


      <div class="filter-container">
        <div class="filters-row">
          <!-- Filter za veličinu -->
          <div class="filter-group">
            <label for="velicina">Veličina:</label>
            <select id="velicina" [(ngModel)]="selectedVelicina" (change)="applyFilters()">
              <option value="">Sve veličine</option>
              <option value="XS">XS</option>
              <option value="S">S</option>
              <option value="M">M</option>
              <option value="L">L</option>
              <option value="XL">XL</option>
              <option value="XXL">XXL</option>
              <option value="XXXL">XXXL</option>
              <option value="Jedna veličina">Jedna veličina</option>
            </select>
          </div>

          <!-- Filter za boju -->
          <div class="filter-group">
            <label for="boja">Boja:</label>
            <select id="boja" [(ngModel)]="selectedBoja" (change)="applyFilters()">
              <option value="">Sve boje</option>
              <option value="bela">Bela</option>
              <option value="crna">Crna</option>
              <option value="crvena">Crvena</option>
              <option value="plava">Plava</option>
              <option value="zelena">Zelena</option>
              <option value="žuta">Žuta</option>
              <option value="narandžasta">Narandžasta</option>
              <option value="ljubičasta">Ljubičasta</option>
            </select>
          </div>

          <!-- Filter za maksimalnu cenu -->
          <div class="filter-group">
            <label for="maxCena">Max Cena:</label>
            <input type="number" id="maxCena" placeholder="Max" [(ngModel)]="maxCena" (input)="applyFilters()">
          </div>
        </div>
      </div>

      <!-- Prikaz artikala -->
      <!-- Prikaz artikala -->
<div class="artikli-container">
  <div class="artikal-card" *ngFor="let artikal of filteredArtikli" [routerLink]="['/artikal', artikal._id]">
    <div class="favourite-icon" (click)="toggleFavourite(artikal._id); $event.stopPropagation()">
      <i *ngIf="isFavourite(artikal._id)" class="fas fa-heart"></i> <!-- Puno srce -->
      <i *ngIf="!isFavourite(artikal._id)" class="far fa-heart"></i> <!-- Prazno srce -->
    </div>

    <img [src]="getArtikalImage(artikal.slike)" alt="Artikal slika" class="artikal-image" />

    <div class="artikal-info">
      <p>Veličina: {{ artikal.velicina }}</p>
      <p>Cena: {{ artikal.cena }} din</p>
    </div>

    <!-- Dugme za dodavanje u korpu, prikazano na hover -->
    <button class="add-to-cart-btn" (click)="addToCart(artikal._id); $event.stopPropagation()">Dodaj u korpu</button>
  </div>
</div>


  </div>
</div>
